SELECT jsonb_build_object('read13_marker','TrackUsageEvent/field'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','TrackUsageEvent','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,user_id,subscription_id,entitlement_grant_id,entitlement_id,track,type,customer_profile_id,candidate_profile_id,professional_profile_id,target_type,target_id,quantity,occurred_at,metadata,semantic_effect_key,source_revision,source_owner,source_id,accepted_at,period_start,period_end,effect_receipt_id,mutation_transaction_id FROM app.track_usage_events WHERE id IN ('adfa809a-28f7-5233-81af-11d48a65dd68'::uuid,'bd0f67d5-9000-5394-9bb9-0ecb9aa5fd2c'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','TrackUsageEvent/field'::text,'position','AFTER'::text);
